const e="zoubian",t=4,n=[{num:1,title:"你一定行！",points:[{id:"DC4-U01-1",name:"一点儿/一个……都/也不/没……",pinyin:"yìdiǎnr / yí ge ... dōu / yě bù / méi ...",type:"",explainEn:"Use this pattern to say 'not at all' or 'not even one'.",structure:"主语 + 一 + 量词/一点儿 +（名词）+ 都/也 + 不/没 + 动词/形容词",examples:[{zh:"我一点儿也不累。",en:"I am not tired at all.",py:"Wǒ yìdiǎnr yě bú lèi."},{zh:"他一杯水都没喝。",en:"He did not drink even one glass of water.",py:"Tā yì bēi shuǐ dōu méi hē."},{zh:"我一个朋友也不认识。",en:"I do not know a single friend.",py:"Wǒ yí ge péngyou yě bú rènshi."}],exercises:[{q:"I am not worried at all.",a:"我一点儿也不担心。",instr:"翻译",instrEn:"Translate into Chinese",body:"I am not worried at all."},{q:"She did not buy even one book.",a:"她一本书都没买。",instr:"翻译",instrEn:"Translate into Chinese",body:"She did not buy even one book."},{q:"He does not understand any Chinese at all.",a:"他一点儿中文都不懂。",instr:"翻译",instrEn:"Translate into Chinese",body:"He does not understand any Chinese at all."}],note:"“一……也/都……”与否定词搭配；过去未发生多用“没”，一般否定多用“不”。",source:"Discover China Student's Book Four (用户上传教材): Language in use",structureEn:"Subject + 一 (yī) + Measure Word / 一点儿 (yìdiǎnr, any) + (Noun) + 都/也 (dōu/yě, even) + 不/没 (bù/méi, not) + Verb / Adjective",noteEn:'"一……也/都……" is used together with a negative word: use 没 (méi) for something that did not happen in the past, and 不 (bù) for general negation.'},{id:"DC4-U01-2",name:"是……的（强调过去动作的细节）",pinyin:"shì ... de",type:"",explainEn:"Use 是…的 to highlight the time, place, or way of a past action.",structure:"主语 + 是 + 时间/地点/方式 + 动词 +（宾语）+ 的",examples:[{zh:"我是昨天到的。",en:"I arrived yesterday.",py:"Wǒ shì zuótiān dào de."},{zh:"这张票是网上买的。",en:"This ticket was bought online.",py:"Zhè zhāng piào shì wǎngshàng mǎi de."},{zh:"他是坐火车来的。",en:"He came by train.",py:"Tā shì zuò huǒchē lái de."}],exercises:[{q:"I came by plane.",a:"我是坐飞机来的。",instr:"翻译",instrEn:"Translate into Chinese",body:"I came by plane."},{q:"She bought the book yesterday.",a:"这本书是她昨天买的。",instr:"翻译",instrEn:"Translate into Chinese",body:"She bought the book yesterday."},{q:"We met at school.",a:"我们是在学校认识的。",instr:"翻译",instrEn:"Translate into Chinese",body:"We met at school."}],note:"动作已发生；强调部分在“是”和“的”之间。",source:"Discover China Student's Book Four (用户上传教材): Language in use",structureEn:"Subject + 是 (shì) + Time / Place / How + Verb + (Object) + 的 (de)",noteEn:"The action has already happened; the part you want to emphasize goes between 是 and 的."},{id:"DC4-U01-3",name:"回/进/上/下 + 来/去（趋向补语）",pinyin:"huí / jìn / shàng / xià + lái / qù",type:"",explainEn:"Use 来 for movement toward the speaker and 去 for movement away.",structure:"动词 + 回/进/上/下 + 来/去",examples:[{zh:"他走进来了。",en:"He walked in toward us.",py:"Tā zǒu jìnlai le."},{zh:"请把书拿上来。",en:"Please bring the book up here.",py:"Qǐng bǎ shū ná shànglai."},{zh:"她跑下去了。",en:"She ran down (away from us).",py:"Tā pǎo xiàqu le."}],exercises:[{q:"Please walk back here.",a:"请走回来。",instr:"翻译",instrEn:"Translate into Chinese",body:"Please walk back here."},{q:"He walked downstairs.",a:"他走下楼去了。",instr:"翻译",instrEn:"Translate into Chinese",body:"He walked downstairs."},{q:"Bring the bag inside.",a:"把包拿进来。",instr:"翻译",instrEn:"Translate into Chinese",body:"Bring the bag inside."}],note:"教材重点为复合趋向；方向以说话人的位置为参照。",source:"Discover China Student's Book Four (用户上传教材): Language in use",structureEn:"Verb + Direction (回 huí / 进 jìn / 上 shàng / 下 xià) + 来 (lái, toward) / 去 (qù, away)",noteEn:"The textbook focuses on compound direction complements (like 走进来, 拿上去). The direction is judged from where the speaker is."},{id:"DC4-U01-4",name:"连……都/也……",pinyin:"lián ... dōu / yě ...",type:"",explainEn:"Use 连…都/也… to mean 'even…', showing surprise or an extreme case.",structure:"连 + 特别的人/事 + 都/也 + 谓语",examples:[{zh:"他连中文歌都会唱。",en:"He can even sing Chinese songs.",py:"Tā lián Zhōngwén gē dōu huì chàng."},{zh:"今天太忙了，我连午饭都没吃。",en:"I was so busy that I did not even eat lunch.",py:"Jīntiān tài máng le, wǒ lián wǔfàn dōu méi chī."},{zh:"连小孩子也知道这个字。",en:"Even a child knows this character.",py:"Lián xiǎo háizi yě zhīdào zhège zì."}],exercises:[{q:"Even the teacher does not know.",a:"连老师都不知道。",instr:"翻译",instrEn:"Translate into Chinese",body:"Even the teacher does not know."},{q:"I did not even have time to rest.",a:"我连休息的时间都没有。",instr:"翻译",instrEn:"Translate into Chinese",body:"I did not even have time to rest."},{q:"She can even speak Japanese.",a:"她连日语都会说。",instr:"翻译",instrEn:"Translate into Chinese",body:"She can even speak Japanese."}],note:"“连”突出意外对象，“都/也”应出现；不是普通的“都”列举。",source:"Discover China Student's Book Four (用户上传教材): Language in use",structureEn:"连 (lián, even) + Surprising Person/Thing + 都/也 (dōu/yě) + Verb/Description",noteEn:"连 highlights a surprising person or thing, and 都 or 也 must follow it. It is not the ordinary 都 that sums up a list."}]},{num:2,title:"你感觉怎么样？",points:[{id:"DC4-U02-1",name:"不得了（极高程度）",pinyin:"bùdéliǎo",type:"",explainEn:"Use 得不得了 after an adjective or state verb to mean 'extremely'.",structure:"主语 + 形容词/状态动词 + 得 + 不得了",examples:[{zh:"今天热得不得了。",en:"It is extremely hot today.",py:"Jīntiān rè de bùdéliǎo."},{zh:"她忙得不得了。",en:"She is extremely busy.",py:"Tā máng de bùdéliǎo."},{zh:"我饿得不得了。",en:"I am terribly hungry.",py:"Wǒ è de bùdéliǎo."}],exercises:[{q:"I am extremely tired.",a:"我累得不得了。",instr:"翻译",instrEn:"Translate into Chinese",body:"I am extremely tired."},{q:"It is terribly cold today.",a:"今天冷得不得了。",instr:"翻译",instrEn:"Translate into Chinese",body:"It is terribly cold today."},{q:"He is extremely happy.",a:"他高兴得不得了。",instr:"翻译",instrEn:"Translate into Chinese",body:"He is extremely happy."}],note:"注意为“形容词/状态动词+得不得了”，而不是单独“不得了”作普通状语。",source:"Discover China Student's Book Four (用户上传教材): Language in use",structureEn:"Subject + Adjective / Feeling Verb + 得 (de) + 不得了 (bùdéliǎo, extremely)",noteEn:"The pattern is adjective / feeling verb + 得不得了. 不得了 is not used on its own here as an ordinary adverb."},{id:"DC4-U02-2",name:"再和又（重复动作）",pinyin:"zài hé yòu",type:"",explainEn:"Use 又 for a repeated past action, and 再 for doing something again later.",structure:"已发生：又 + 动词；将来/要求：再 + 动词",examples:[{zh:"他昨天又迟到了。",en:"He was late again yesterday.",py:"Tā zuótiān yòu chídào le."},{zh:"请再说一遍。",en:"Please say it again.",py:"Qǐng zài shuō yí biàn."},{zh:"明天我们再来。",en:"We will come again tomorrow.",py:"Míngtiān wǒmen zài lái."}],exercises:[{q:"He called me again yesterday.",a:"他昨天又给我打电话了。",instr:"翻译",instrEn:"Translate into Chinese",body:"He called me again yesterday."},{q:"Please try again.",a:"请再试一次。",instr:"翻译",instrEn:"Translate into Chinese",body:"Please try again."},{q:"Let's meet again next week.",a:"我们下周再见。",instr:"翻译",instrEn:"Translate into Chinese",body:"Let's meet again next week."}],note:"避免把“又”和“再”机械地等同于英文again；根据动作是否已发生选择。",source:"Discover China Student's Book Four (用户上传教材): Language in use",structureEn:"Past / already happened: 又 (yòu, again) + Verb; Future / request: 再 (zài, again) + Verb",noteEn:`Don't treat 又 and 再 as simply meaning "again". Choose by whether the action has already happened (又) or has not happened yet (再).`},{id:"DC4-U02-3",name:"一下和一点儿（轻微语气）",pinyin:"yíxià hé yìdiǎnr",type:"",explainEn:"Use 一下 to make an action short or polite. Use 一点儿 to mean a small amount.",structure:"动词 + 一下；动词 + 一点儿 + 名词；（动词 +）形容词 + 一点儿",examples:[{zh:"请你等一下。",en:"Please wait a moment.",py:"Qǐng nǐ děng yíxià."},{zh:"我想喝一点儿水。",en:"I would like a little water.",py:"Wǒ xiǎng hē yìdiǎnr shuǐ."},{zh:"你可以说慢一点儿吗？",en:"Could you speak a little more slowly?",py:"Nǐ kěyǐ shuō màn yìdiǎnr ma?"}],exercises:[{q:"Please look at this.",a:"请看一下这个。",instr:"翻译",instrEn:"Translate into Chinese",body:"Please look at this."},{q:"I would like a little tea.",a:"我想喝一点儿茶。",instr:"翻译",instrEn:"Translate into Chinese",body:"I would like a little tea."},{q:"Please speak a little louder.",a:"请说得大声一点儿。",instr:"翻译",instrEn:"Translate into Chinese",body:"Please speak a little louder."}],note:"一下修饰动作；一点儿表达数量或程度。",source:"Discover China Student's Book Four (用户上传教材): Language in use",structureEn:"Verb + 一下 (yíxià, briefly); Verb + 一点儿 (yìdiǎnr, a little) + Noun; (Verb +) Adjective + 一点儿",noteEn:"一下 goes with an action; 一点儿 shows an amount or a degree."},{id:"DC4-U02-4",name:"起来（动作/新状态开始）",pinyin:"qǐlái",type:"",explainEn:"Use 起来 after a verb or adjective to show something starts.",structure:"动词/形容词 + 起来（常带“了”）；带宾语：动词 + 起 + 宾语 + 来",examples:[{zh:"孩子哭起来了。",en:"The child started crying.",py:"Háizi kū qǐlai le."},{zh:"天气慢慢热起来了。",en:"The weather is getting warmer.",py:"Tiānqì mànmàn rè qǐlai le."},{zh:"大家都笑起来了。",en:"Everyone started laughing.",py:"Dàjiā dōu xiào qǐlai le."}],exercises:[{q:"It started raining.",a:"下起雨来了。",instr:"翻译",instrEn:"Translate into Chinese",body:"It started raining."},{q:"He began to sing.",a:"他唱起歌来了。",instr:"翻译",instrEn:"Translate into Chinese",body:"He began to sing."},{q:"Everyone started chatting.",a:"大家聊起来了。",instr:"翻译",instrEn:"Translate into Chinese",body:"Everyone started chatting."}],note:"这里讲开始义，不与“想起来、看起来”等引申义混淆。",source:"Discover China Student's Book Four (用户上传教材): Language in use",structureEn:"Verb / Adjective + 起来 (qǐlái, start to) (+ 了 le); with an object: Verb + 起 (qǐ) + Object + 来 (lái)",noteEn:`Here 起来 means "to start". Don't mix it up with other uses such as 想起来 (to remember) or 看起来 (to seem).`}]},{num:3,title:"让您的旅行没有后顾之忧！",points:[{id:"DC4-U03-1",name:"至于（引出新话题）",pinyin:"zhìyú",type:"",explainEn:"Use 至于 to move to a related point: 'as for…'.",structure:"前面的情况。至于 + 新话题，+ 补充说明",examples:[{zh:"去不去我还没决定，至于时间，我们以后再说。",en:"I have not decided whether to go. As for the time, we can talk later.",py:"Qù bu qù wǒ hái méi juédìng, zhìyú shíjiān, wǒmen yǐhòu zài shuō."},{zh:"我喜欢这里的食物，至于天气，我还不习惯。",en:"I like the food here; as for the weather, I am not used to it.",py:"Wǒ xǐhuan zhèlǐ de shíwù, zhìyú tiānqì, wǒ hái bù xíguàn."},{zh:"车票买好了，至于酒店，还没订。",en:"The tickets are bought; as for the hotel, it is not booked yet.",py:"Chēpiào mǎi hǎo le, zhìyú jiǔdiàn, hái méi dìng."}],exercises:[{q:"The hotel is fine; as for the price, I will ask tomorrow.",a:"酒店不错，至于价格，我明天再问。",instr:"翻译",instrEn:"Translate into Chinese",body:"The hotel is fine; as for the price, I will ask tomorrow."},{q:"The luggage is packed; as for the hotel, we have already booked it.",a:"行李收拾好了，至于酒店，我们已经订好了。",instr:"翻译",instrEn:"Translate into Chinese",body:"The luggage is packed; as for the hotel, we have already booked it."},{q:"That's all for today; as for this question, we can discuss it later.",a:"今天就到这儿，至于这个问题，我们可以以后再讨论。",instr:"翻译",instrEn:"Translate into Chinese",body:"That's all for today; as for this question, we can discuss it later."}],note:"是篇章层面的转话题结构；新话题应与前文相关。",source:"Discover China Student's Book Four (用户上传教材): Language in use",structureEn:"Previous Point. 至于 (zhìyú, as for) + New Topic, + Comment",noteEn:"至于 switches topics across sentences; the new topic should be related to what was said before."},{id:"DC4-U03-2",name:"不如（比较）",pinyin:"bùrú",type:"",explainEn:"Use A 不如 B to say A is not as good as B in some way.",structure:"A + 不如 + B +（形容词/动词短语）",examples:[{zh:"坐公交车不如坐地铁快。",en:"Taking the bus is not as fast as taking the subway.",py:"Zuò gōngjiāochē bùrú zuò dìtiě kuài."},{zh:"我的中文不如她好。",en:"My Chinese is not as good as hers.",py:"Wǒ de Zhōngwén bùrú tā hǎo."},{zh:"今天的天气不如昨天好。",en:"Today's weather is not as good as yesterday's.",py:"Jīntiān de tiānqì bùrú zuótiān hǎo."}],exercises:[{q:"This room is not as big as that one.",a:"这个房间不如那个大。",instr:"翻译",instrEn:"Translate into Chinese",body:"This room is not as big as that one."},{q:"Walking is not as fast as cycling.",a:"走路不如骑车快。",instr:"翻译",instrEn:"Translate into Chinese",body:"Walking is not as fast as cycling."},{q:"I am not as tall as you.",a:"我不如你高。",instr:"翻译",instrEn:"Translate into Chinese",body:"I am not as tall as you."}],note:"“不如”表示比较不及，不是单纯建议意义的“不如我们……”。",source:"Discover China Student's Book Four (用户上传教材): Language in use",structureEn:"A + 不如 (bùrú, not as…as) + B + (Adjective / Verb Phrase)",noteEn:'Here 不如 compares two things ("not as … as"). It is not the 不如 used for suggestions, as in 不如我们…… ("we might as well…").'},{id:"DC4-U03-3",name:"……分之……（分数/百分比）",pinyin:"... fēn zhī ...",type:"",explainEn:"Say the denominator first, then 分之, then the numerator.",structure:"分母 + 分之 + 分子；百分之 + 数字",examples:[{zh:"我们班三分之一的学生住在学校。",en:"One third of our class lives at school.",py:"Wǒmen bān sān fēn zhī yī de xuésheng zhù zài xuéxiào."},{zh:"百分之五十的人喜欢这个办法。",en:"Fifty percent of people like this method.",py:"Bǎi fēn zhī wǔshí de rén xǐhuan zhège bànfǎ."},{zh:"我完成了四分之三的作业。",en:"I finished three quarters of the homework.",py:"Wǒ wánchéng le sì fēn zhī sān de zuòyè."}],exercises:[{q:"One half of the students are here.",a:"二分之一的学生在这儿。",instr:"翻译",instrEn:"Translate into Chinese",body:"One half of the students are here."},{q:"Twenty percent of the people agreed.",a:"百分之二十的人同意了。",instr:"翻译",instrEn:"Translate into Chinese",body:"Twenty percent of the people agreed."},{q:"I have finished two thirds of the work.",a:"我完成了三分之二的工作。",instr:"翻译",instrEn:"Translate into Chinese",body:"I have finished two thirds of the work."}],note:"中文顺序与英语分数表达不同；百分数读“百分之+数”。",source:"Discover China Student's Book Four (用户上传教材): Language in use",structureEn:"Denominator + 分之 (fēn zhī, over) + Numerator; 百分之 (bǎi fēn zhī, percent) + Number",noteEn:"Chinese puts the parts of a fraction in a different order from English. Percentages are read as 百分之 + number."},{id:"DC4-U03-4",name:"还 + 正面形容词（语气缓和）",pinyin:"hái + zhèngmiàn xíngróngcí",type:"",explainEn:"Use 还 before a positive adjective to mean 'quite / reasonably', not very strong praise.",structure:"主语 + 还 + 好/不错/方便/可以等",examples:[{zh:"这家饭馆还不错。",en:"This restaurant is quite good.",py:"Zhè jiā fànguǎn hái búcuò."},{zh:"这个办法还可以。",en:"This method is okay.",py:"Zhège bànfǎ hái kěyǐ."},{zh:"这里的交通还方便。",en:"Transport here is reasonably convenient.",py:"Zhèlǐ de jiāotōng hái fāngbiàn."}],exercises:[{q:"This hotel is quite good.",a:"这家酒店还不错。",instr:"翻译",instrEn:"Translate into Chinese",body:"This hotel is quite good."},{q:"His Chinese is OK.",a:"他的中文还可以。",instr:"翻译",instrEn:"Translate into Chinese",body:"His Chinese is OK."},{q:"The price is not bad.",a:"这个价格还行。",instr:"翻译",instrEn:"Translate into Chinese",body:"The price is not bad."}],note:"教材强调“还”缓和正面评价，非表示“still”的时间副词。",source:"Discover China Student's Book Four (用户上传教材): Language in use",structureEn:"Subject + 还 (hái, quite / reasonably) + Positive Adjective",noteEn:'The textbook stresses that this 还 softens a positive comment. It is not the time word 还 meaning "still".'}]},{num:4,title:"欢迎大家的到来！",points:[{id:"DC4-U04-1",name:"动宾离合词",pinyin:"dòng-bīn líhécí",type:"",explainEn:"Some verb-object words can split. Put time, number, or 了 between the two parts.",structure:"动词 + 了/数量/时长 + 宾语；如 睡了一个好觉",examples:[{zh:"我昨晚睡了一个好觉。",en:"I slept well last night.",py:"Wǒ zuówǎn shuì le yí ge hǎo jiào."},{zh:"我们见过两次面。",en:"We have met twice.",py:"Wǒmen jiàn guo liǎng cì miàn."},{zh:"他唱了一首歌。",en:"He sang a song.",py:"Tā chàng le yì shǒu gē."}],exercises:[{q:"I slept for eight hours.",a:"我睡了八个小时的觉。",instr:"翻译",instrEn:"Translate into Chinese",body:"I slept for eight hours."},{q:"We met once yesterday.",a:"我们昨天见了一次面。",instr:"翻译",instrEn:"Translate into Chinese",body:"We met once yesterday."},{q:"She danced for an hour.",a:"她跳了一个小时的舞。",instr:"翻译",instrEn:"Translate into Chinese",body:"She danced for an hour."}],note:"注意如“见面、睡觉、跳舞”中间可插入成分，不是每个动宾短语都以同样方式离合。",source:"Discover China Student's Book Four (用户上传教材): Language in use",structureEn:"Verb Part + 了 (le) / Amount / Time + Object Part; e.g. 睡 + 了一个好 + 觉",noteEn:"Words like 见面, 睡觉 and 跳舞 can take other words in the middle, but not every verb-object phrase splits in the same way."},{id:"DC4-U04-2",name:"通过（方法/途径）",pinyin:"tōngguò",type:"",explainEn:"Use 通过 to show the way or method used to achieve something: 'through / by'.",structure:"主语 + 通过 + 方法/途径 + 动词 + 结果",examples:[{zh:"我通过朋友认识了他。",en:"I met him through a friend.",py:"Wǒ tōngguò péngyou rènshi le tā."},{zh:"我们通过邮件联系。",en:"We keep in touch by email.",py:"Wǒmen tōngguò yóujiàn liánxì."},{zh:"她通过练习提高了中文水平。",en:"She improved her Chinese through practice.",py:"Tā tōngguò liànxí tígāo le Zhōngwén shuǐpíng."}],exercises:[{q:"I found the job through a friend.",a:"我通过朋友找到了工作。",instr:"翻译",instrEn:"Translate into Chinese",body:"I found the job through a friend."},{q:"We learned the news online.",a:"我们通过网络知道了这个消息。",instr:"翻译",instrEn:"Translate into Chinese",body:"We learned the news online."},{q:"He improved his English by listening.",a:"他通过听力练习提高了英语水平。",instr:"翻译",instrEn:"Translate into Chinese",body:"He improved his English by listening."}],note:"说明达成结果的方式；不是空间移动意义的“通过大门”。",source:"Discover China Student's Book Four (用户上传教材): Language in use",structureEn:"Subject + 通过 (tōngguò, through/by) + Method + Verb + Result",noteEn:'It shows the way a result is reached. It is not 通过 in the physical sense of "passing through", as in 通过大门.'},{id:"DC4-U04-3",name:"由（动作执行者）",pinyin:"yóu",type:"",explainEn:"Use 由 to name who is responsible for doing an action. It is formal.",structure:"事情/动作 + 由 + 人/机构 + 动词",examples:[{zh:"活动由学校组织。",en:"The school organizes the event.",py:"Huódòng yóu xuéxiào zǔzhī."},{zh:"这件事由我负责。",en:"I am responsible for this matter.",py:"Zhè jiàn shì yóu wǒ fùzé."},{zh:"会议由王老师主持。",en:"The meeting is hosted by Teacher Wang.",py:"Huìyì yóu Wáng lǎoshī zhǔchí."}],exercises:[{q:"The hotel is booked by the company.",a:"酒店由公司预订。",instr:"翻译",instrEn:"Translate into Chinese",body:"The hotel is booked by the company."},{q:"This job is handled by him.",a:"这项工作由他负责。",instr:"翻译",instrEn:"Translate into Chinese",body:"This job is handled by him."},{q:"The trip is arranged by the teacher.",a:"旅行由老师安排。",instr:"翻译",instrEn:"Translate into Chinese",body:"The trip is arranged by the teacher."}],note:"较正式，强调执行者或责任人；不可与“被”的所有被动用法机械等同。",source:"Discover China Student's Book Four (用户上传教材): Language in use",structureEn:"Event / Task + 由 (yóu, by) + Person / Organization + Verb",noteEn:"由 is fairly formal and stresses who does the action or is responsible for it. Don't treat it as the same as every passive use of 被."},{id:"DC4-U04-4",name:"书面语中的单音节形式",pinyin:"shūmiànyǔ zhōng de dān yīnjié xíngshì",type:"",explainEn:"In formal writing, some two-character words can appear as shorter one-character forms.",structure:"口语双音节词 → 书面单音节词；例如 如果→如，或者→或",examples:[{zh:"如有问题，请联系我们。",en:"If you have questions, please contact us.",py:"Rú yǒu wèntí, qǐng liánxì wǒmen."},{zh:"请于周五前回复。",en:"Please reply before Friday.",py:"Qǐng yú zhōuwǔ qián huífù."},{zh:"请通过邮件或电话联系。",en:"Please contact us by email or phone.",py:"Qǐng tōngguò yóujiàn huò diànhuà liánxì."}],exercises:[{q:"If you need help, please call.",a:"如需帮助，请打电话。",instr:"翻译",instrEn:"Translate into Chinese",body:"If you need help, please call."},{q:"Please reply by email or phone.",a:"请用邮件或电话回复。",instr:"翻译",instrEn:"Translate into Chinese",body:"Please reply by email or phone."},{q:"If there are any changes, please tell me.",a:"如有变化，请告诉我。",instr:"翻译",instrEn:"Translate into Chinese",body:"If there are any changes, please tell me."}],note:"本项是教材语体知识，不是一个单一生产性句型；练习选择教材例示的常见书面单音节词。",source:"Discover China Student's Book Four (用户上传教材): Language in use",structureEn:"Everyday Two-character Word → Formal One-character Word (e.g., 如果 → 如, 或者 → 或)",noteEn:"This point is about formal written style, not one fixed sentence pattern. The practice uses common one-character formal words shown in the textbook."}]},{num:5,title:"我一定尽力而为！",points:[{id:"DC4-U05-1",name:"倒（转折/让步）",pinyin:"dào",type:"",explainEn:"Use 倒 to show a contrasting or unexpected positive or negative point.",structure:"先说情况A，主语 + 倒 + 相反/补充判断",examples:[{zh:"这家店很小，东西倒不错。",en:"This shop is small, but the products are actually good.",py:"Zhè jiā diàn hěn xiǎo, dōngxi dào búcuò."},{zh:"他中文说得不多，发音倒很好。",en:"He does not speak much Chinese, but his pronunciation is good.",py:"Tā Zhōngwén shuō de bù duō, fāyīn dào hěn hǎo."},{zh:"这个地方不大，人倒挺多。",en:"This place isn't big, but there are actually quite a lot of people.",py:"Zhège dìfang bú dà, rén dào tǐng duō."}],exercises:[{q:"The room is small, but it is quite clean.",a:"房间很小，倒挺干净。",instr:"翻译",instrEn:"Translate into Chinese",body:"The room is small, but it is quite clean."},{q:"He is young, but he has a lot of experience.",a:"他很年轻，经验倒很丰富。",instr:"翻译",instrEn:"Translate into Chinese",body:"He is young, but he has a lot of experience."},{q:"It's cheap, but the quality is actually good.",a:"价格很便宜，质量倒不错。",instr:"翻译",instrEn:"Translate into Chinese",body:"It's cheap, but the quality is actually good."}],note:"“倒”表达与预期不同或让步，常隐含对比。",source:"Discover China Student's Book Four (用户上传教材): Language in use",structureEn:"Situation A, Subject + 倒 (dào, actually / though) + Contrasting Comment",noteEn:"倒 shows something different from what you would expect, or a concession; it usually implies a contrast."},{id:"DC4-U05-2",name:"好好 + 动词（认真/充分地做）",pinyin:"hǎohǎo + dòngcí",type:"",explainEn:"Use 好好 before a verb to mean 'do it properly / carefully / well'.",structure:"主语 + 好好 + 动词（+ 结果）",examples:[{zh:"你先好好休息。",en:"Please get some proper rest first.",py:"Nǐ xiān hǎohǎo xiūxi."},{zh:"我想好好学习中文。",en:"I want to study Chinese seriously.",py:"Wǒ xiǎng hǎohǎo xuéxí Zhōngwén."},{zh:"我们好好讨论一下吧。",en:"Let's discuss this carefully.",py:"Wǒmen hǎohǎo tǎolùn yíxià ba."}],exercises:[{q:"Please think carefully.",a:"请好好想一想。",instr:"翻译",instrEn:"Translate into Chinese",body:"Please think carefully."},{q:"You need to prepare well.",a:"你要好好准备。",instr:"翻译",instrEn:"Translate into Chinese",body:"You need to prepare well."},{q:"We should make good use of the time.",a:"我们要好好利用时间。",instr:"翻译",instrEn:"Translate into Chinese",body:"We should make good use of the time."}],note:"教材还允许与“想/应该/得”等能愿词连用，表示认真做、做得更好。",source:"Discover China Student's Book Four (用户上传教材): Language in use",structureEn:"Subject + 好好 (hǎohǎo, properly / carefully) + Verb",noteEn:'The textbook also allows it after words like 想, 应该 and 得 (děi, "must"), meaning to do something seriously or do it better.'},{id:"DC4-U05-3",name:"既然……，就/那……",pinyin:"jìrán ... jiù / nà ...",type:"",explainEn:"Use 既然…就… when the reason is already known: 'since…, then…'.",structure:"既然 + 已知事实，就/那 + 结论/建议",examples:[{zh:"既然你累了，就休息一下吧。",en:"Since you are tired, take a rest.",py:"Jìrán nǐ lèi le, jiù xiūxi yíxià ba."},{zh:"既然已经到了，我们就进去吧。",en:"Since we have arrived, let's go in.",py:"Jìrán yǐjīng dào le, wǒmen jiù jìnqu ba."},{zh:"既然你不喜欢，那就别买。",en:"Since you do not like it, don't buy it.",py:"Jìrán nǐ bù xǐhuan, nà jiù bié mǎi."}],exercises:[{q:"Since it is raining, let's stay home.",a:"既然下雨了，我们就待在家里吧。",instr:"翻译",instrEn:"Translate into Chinese",body:"Since it is raining, let's stay home."},{q:"Since you have time, please help me.",a:"既然你有时间，就帮帮我吧。",instr:"翻译",instrEn:"Translate into Chinese",body:"Since you have time, please help me."},{q:"Since everyone agrees, let's start.",a:"既然大家都同意，我们就开始吧。",instr:"翻译",instrEn:"Translate into Chinese",body:"Since everyone agrees, let's start."}],note:"既然引出双方已知或认可的事实，不等同假设的“如果”。",source:"Discover China Student's Book Four (用户上传教材): Language in use",structureEn:"既然 (jìrán, since) + Known Fact, 就 (jiù, then) / 那 (nà, then) + Result",noteEn:'既然 introduces a fact that both people already know or accept. It is not the same as 如果 ("if"), which is only a guess.'},{id:"DC4-U05-4",name:"再……不过了（程度极高）",pinyin:"zài ... búguò le",type:"",explainEn:"Use 再 + adjective + 不过了 to mean 'couldn't be more…'.",structure:"再 + 形容词/心理动词 + 不过了",examples:[{zh:"这个办法再好不过了。",en:"This method could not be better.",py:"Zhège bànfǎ zài hǎo búguò le."},{zh:"这个时间再合适不过了。",en:"This time could not be more suitable.",py:"Zhège shíjiān zài héshì búguò le."},{zh:"能见到你，我再高兴不过了。",en:"I could not be happier to see you.",py:"Néng jiàndào nǐ, wǒ zài gāoxìng búguò le."}],exercises:[{q:"This is the best time possible.",a:"这个时间再好不过了。",instr:"翻译",instrEn:"Translate into Chinese",body:"This is the best time possible."},{q:"Your idea couldn't be better.",a:"你的主意再好不过了。",instr:"翻译",instrEn:"Translate into Chinese",body:"Your idea couldn't be better."},{q:"I couldn't be more satisfied.",a:"我再满意不过了。",instr:"翻译",instrEn:"Translate into Chinese",body:"I couldn't be more satisfied."}],note:"惯用结构，整体表示极端程度，不应按字面误解为“再做一次”。",source:"Discover China Student's Book Four (用户上传教材): Language in use",structureEn:"再 (zài) + Adjective / Feeling Verb + 不过了 (bú guò le, could not be more…)",noteEn:`This is a fixed expression: as a whole it means "as … as can be". Don't read 再 literally as "do it again".`}]},{num:6,title:"你们那个报告得很好！",points:[{id:"DC4-U06-1",name:"……死了（极高程度）",pinyin:"... sǐ le",type:"",explainEn:"Use adjective + 死了 to mean 'extremely'. It is very colloquial.",structure:"形容词/心理动词 + 死了",examples:[{zh:"我累死了。",en:"I am exhausted.",py:"Wǒ lèi sǐ le."},{zh:"今天热死了。",en:"It is unbearably hot today.",py:"Jīntiān rè sǐ le."},{zh:"听到这个消息，我高兴死了。",en:"I was extremely happy to hear this.",py:"Tīngdào zhège xiāoxi, wǒ gāoxìng sǐ le."}],exercises:[{q:"I'm terribly hungry.",a:"我饿死了。",instr:"翻译",instrEn:"Translate into Chinese",body:"I'm terribly hungry."},{q:"It's so cold!",a:"冷死了！",instr:"翻译",instrEn:"Translate into Chinese",body:"It's so cold!"},{q:"He is extremely busy.",a:"他忙死了。",instr:"翻译",instrEn:"Translate into Chinese",body:"He is extremely busy."}],note:"夸张口语，“死了”通常不是字面死亡；可修饰正面或负面感受。",source:"Discover China Student's Book Four (用户上传教材): Language in use",structureEn:"Adjective / Feeling Verb + 死了 (sǐ le, extremely)",noteEn:"This is a colloquial exaggeration: 死了 usually has nothing to do with real death, and it can follow both good and bad feelings."},{id:"DC4-U06-2",name:"要是/如果……就好了（愿望）",pinyin:"yàoshi / rúguǒ ... jiù hǎo le",type:"",explainEn:"Use 要是/如果…就好了 to say 'it would be great if…'.",structure:"要是/如果 + 想象的情况，就好了",examples:[{zh:"要是明天不下雨就好了。",en:"It would be great if it did not rain tomorrow.",py:"Yàoshi míngtiān bú xià yǔ jiù hǎo le."},{zh:"如果我有更多时间就好了。",en:"I wish I had more time.",py:"Rúguǒ wǒ yǒu gèng duō shíjiān jiù hǎo le."},{zh:"要是你能来就好了。",en:"It would be great if you could come.",py:"Yàoshi nǐ néng lái jiù hǎo le."}],exercises:[{q:"If only I could speak Chinese better.",a:"要是我的中文能说得更好就好了。",instr:"翻译",instrEn:"Translate into Chinese",body:"If only I could speak Chinese better."},{q:"It would be great if tomorrow were a holiday.",a:"如果明天放假就好了。",instr:"翻译",instrEn:"Translate into Chinese",body:"It would be great if tomorrow were a holiday."},{q:"I wish I could go with you.",a:"要是我能跟你一起去就好了。",instr:"翻译",instrEn:"Translate into Chinese",body:"I wish I could go with you."}],note:"表达主观愿望，不是普通条件复句的事实判断。",source:"Discover China Student's Book Four (用户上传教材): Language in use",structureEn:"要是 (yàoshi, if) / 如果 (rúguǒ, if) + Wish, 就好了 (jiù hǎo le, it would be great)",noteEn:'It expresses a personal wish, not a statement of fact like an ordinary "if…, then…" sentence.'},{id:"DC4-U06-3",name:"可（加强语气）",pinyin:"kě",type:"",explainEn:"Use 可 in speech to make a statement stronger: 'really / indeed'.",structure:"主语 + 可 + 动词短语/形容词（+了）",examples:[{zh:"这可太好了！",en:"This is really great!",py:"Zhè kě tài hǎo le!"},{zh:"你可别忘了。",en:"You really must not forget.",py:"Nǐ kě bié wàng le."},{zh:"他可认真了。",en:"He is really serious.",py:"Tā kě rènzhēn le."}],exercises:[{q:"You really mustn't be late!",a:"你可别迟到了！",instr:"翻译",instrEn:"Translate into Chinese",body:"You really mustn't be late!"},{q:"This is really important.",a:"这可重要了。",instr:"翻译",instrEn:"Translate into Chinese",body:"This is really important."},{q:"He is really good at Chinese.",a:"他的中文可好了。",instr:"翻译",instrEn:"Translate into Chinese",body:"He is really good at Chinese."}],note:"口语中通过“可”加强肯定、提醒或惊讶，不能一律译为can。",source:"Discover China Student's Book Four (用户上传教材): Language in use",structureEn:"Subject + 可 (kě, really / indeed) + Verb Phrase / Adjective (+ 了 le)",noteEn:`In speech, 可 makes a statement, a reminder or a surprise stronger. Don't always translate it as "can".`},{id:"DC4-U06-4",name:"反正（理由/态度）",pinyin:"fǎnzhèng",type:"",explainEn:"Use 反正 to mean 'anyway'. The speaker thinks the result or decision is the same.",structure:"反正 + 原因/结论 + 后续态度",examples:[{zh:"反正明天放假，我们可以晚一点儿起床。",en:"Tomorrow's a holiday anyway, so we can get up a bit later.",py:"Fǎnzhèng míngtiān fàngjià, wǒmen kěyǐ wǎn yìdiǎnr qǐchuáng."},{zh:"我不去，反正我也不喜欢。",en:"I won't go; I don't like it anyway.",py:"Wǒ bú qù, fǎnzhèng wǒ yě bù xǐhuan."},{zh:"反正你已经来了，就一起吃饭吧。",en:"Since you're here anyway, let's eat together.",py:"Fǎnzhèng nǐ yǐjīng lái le, jiù yìqǐ chī fàn ba."}],exercises:[{q:"I have time today anyway, so I'll go with you.",a:"反正我今天有时间，我陪你去吧。",instr:"翻译",instrEn:"Translate into Chinese",body:"I have time today anyway, so I'll go with you."},{q:"We're already late anyway, so don't rush.",a:"反正已经晚了，别着急了。",instr:"翻译",instrEn:"Translate into Chinese",body:"We're already late anyway, so don't rush."},{q:"It's not expensive anyway, so just buy it.",a:"反正这个不贵，你就买吧。",instr:"翻译",instrEn:"Translate into Chinese",body:"It's not expensive anyway, so just buy it."}],note:"可在句首或分句开头出现；表达“无论怎样，态度不变”。",source:"Discover China Student's Book Four (用户上传教材): Language in use",structureEn:"反正 (fǎnzhèng, anyway) + Reason / Judgment, + Decision",noteEn:'反正 can come at the start of a sentence or of a clause. It means "whatever happens, my view stays the same".'}]},{num:7,title:"顾客永远是对的！",points:[{id:"DC4-U07-1",name:"怎么（表示“怎么会/怎么回事”）",pinyin:"zěnme",type:"",explainEn:"Use 怎么 to ask 'how come / why', often with surprise.",structure:"主语 + 怎么 + 动词/形容词 + 了/呢？",examples:[{zh:"你怎么还没走？",en:"How come you have not left yet?",py:"Nǐ zěnme hái méi zǒu?"},{zh:"他怎么生气了？",en:"Why did he get angry?",py:"Tā zěnme shēngqì le?"},{zh:"你怎么这么累？",en:"How come you are so tired?",py:"Nǐ zěnme zhème lèi?"}],exercises:[{q:"How come you are late?",a:"你怎么迟到了？",instr:"翻译",instrEn:"Translate into Chinese",body:"How come you are late?"},{q:"Why isn't he here yet?",a:"他怎么还没来？",instr:"翻译",instrEn:"Translate into Chinese",body:"Why isn't he here yet?"},{q:"How come this is so expensive?",a:"这个怎么这么贵？",instr:"翻译",instrEn:"Translate into Chinese",body:"How come this is so expensive?"}],note:"这里不是询问方法的“怎么做”，而是带惊讶语气的原因问句。",source:"Discover China Student's Book Four (用户上传教材): Language in use",structureEn:"Subject + 怎么 (zěnme, how come) + Verb / Adjective (+ 了 le / 呢 ne)?",noteEn:'This is not 怎么 asking how to do something (怎么做); it asks "why / how come", with a tone of surprise.'},{id:"DC4-U07-2",name:"到底/究竟（加强追问）",pinyin:"dàodǐ / jiūjìng",type:"",explainEn:"Use 到底 or 究竟 in a question to ask 'exactly / after all'.",structure:"主语 + 到底/究竟 + 疑问词/问句？",examples:[{zh:"你到底想去哪儿？",en:"Where exactly do you want to go?",py:"Nǐ dàodǐ xiǎng qù nǎr?"},{zh:"这究竟是怎么回事？",en:"What exactly happened?",py:"Zhè jiūjìng shì zěnme huí shì?"},{zh:"他到底来不来？",en:"Is he coming or not, after all?",py:"Tā dàodǐ lái bu lái?"}],exercises:[{q:"What exactly do you mean?",a:"你到底是什么意思？",instr:"翻译",instrEn:"Translate into Chinese",body:"What exactly do you mean?"},{q:"When exactly will the meeting start?",a:"会议究竟什么时候开始？",instr:"翻译",instrEn:"Translate into Chinese",body:"When exactly will the meeting start?"},{q:"Where on earth is my phone?",a:"我的手机到底在哪儿？",instr:"翻译",instrEn:"Translate into Chinese",body:"Where on earth is my phone?"}],note:"“究竟”较正式；“到底”口语常见，两者都加强提问语气。",source:"Discover China Student's Book Four (用户上传教材): Language in use",structureEn:"Subject + 到底 (dàodǐ) / 究竟 (jiūjìng, exactly) + Question?",noteEn:"究竟 is more formal; 到底 is common in everyday speech. Both make a question more insistent."},{id:"DC4-U07-3",name:"不过/只不过/只是……罢了（弱化情况）",pinyin:"búguò / zhǐ búguò / zhǐshì ... bàle",type:"",explainEn:"Use 不过/只是…罢了 to mean 'only / merely', making something seem less important.",structure:"主语 + 不过/只不过/只是 + 动词/名词 + 罢了",examples:[{zh:"我只是问问罢了。",en:"I was only asking.",py:"Wǒ zhǐshì wènwen bàle."},{zh:"这不过是个小问题罢了。",en:"This is only a small problem.",py:"Zhè búguò shì ge xiǎo wèntí bàle."},{zh:"他不过是开个玩笑罢了。",en:"He was only joking.",py:"Tā búguò shì kāi ge wánxiào bàle."}],exercises:[{q:"I only want to help.",a:"我只是想帮忙罢了。",instr:"翻译",instrEn:"Translate into Chinese",body:"I only want to help."},{q:"It's just a misunderstanding.",a:"这不过是个误会罢了。",instr:"翻译",instrEn:"Translate into Chinese",body:"It's just a misunderstanding."},{q:"It was only a small mistake.",a:"这只不过是一个小错误罢了。",instr:"翻译",instrEn:"Translate into Chinese",body:"It was only a small mistake."}],note:"教材标题把“不过/只不过/只是……罢了”作为弱化表达；避免与表示转折的“不过”混淆。",source:"Discover China Student's Book Four (用户上传教材): Language in use",structureEn:"Subject + 不过 (búguò, merely) / 只不过 (zhǐ búguò, only) / 只是 (zhǐshì, just) + Verb / Noun + 罢了 (bàle, that's all)",noteEn:`The textbook groups 不过 / 只不过 / 只是……罢了 as ways to play something down ("only, that's all"). Don't confuse this with 不过 meaning "but".`},{id:"DC4-U07-4",name:"不但/不只/不仅/不光……而且/还/也……",pinyin:"búdàn / bùzhǐ / bùjǐn / bùguāng ... érqiě / hái / yě ...",type:"",explainEn:"Use this pattern to mean 'not only…, but also…'.",structure:"不但/不只/不仅/不光 + A，而且/还/也 + B",examples:[{zh:"她不仅会中文，还会英语。",en:"She speaks not only Chinese but also English.",py:"Tā bùjǐn huì Zhōngwén, hái huì Yīngyǔ."},{zh:"这个工作不但有意思，而且很重要。",en:"This job is not only interesting but also important.",py:"Zhège gōngzuò búdàn yǒu yìsi, érqiě hěn zhòngyào."},{zh:"他不光帮了我，还给了我建议。",en:"He not only helped me but also gave me advice.",py:"Tā bùguāng bāng le wǒ, hái gěi le wǒ jiànyì."}],exercises:[{q:"She is not only kind but also patient.",a:"她不但善良，而且有耐心。",instr:"翻译",instrEn:"Translate into Chinese",body:"She is not only kind but also patient."},{q:"This hotel is not only clean but also cheap.",a:"这家酒店不仅干净，而且便宜。",instr:"翻译",instrEn:"Translate into Chinese",body:"This hotel is not only clean but also cheap."},{q:"He not only studies but also works.",a:"他不只学习，还工作。",instr:"翻译",instrEn:"Translate into Chinese",body:"He not only studies but also works."}],note:"第二分句还可用“还/也/而且”，不用每次都用“而且”。",source:"Discover China Student's Book Four (用户上传教材): Language in use",structureEn:"不但 (búdàn) / 不只 (bùzhǐ) / 不仅 (bùjǐn) / 不光 (bùguāng, not only) + A, 而且 (érqiě) / 还 (hái) / 也 (yě, but also) + B",noteEn:"The second part can also use 还 or 也 — you don't have to use 而且 every time."}]},{num:8,title:"云南真是个好地方！",points:[{id:"DC4-U08-1",name:"后来和然后",pinyin:"hòulái hé ránhòu",type:"",explainEn:"后来 means 'later' in a story. 然后 means 'then' between steps or events.",structure:"过去情况 + 后来 + 变化；动作1，然后 + 动作2",examples:[{zh:"我以前住北京，后来搬到了上海。",en:"I used to live in Beijing and later moved to Shanghai.",py:"Wǒ yǐqián zhù Běijīng, hòulái bān dào le Shànghǎi."},{zh:"先买票，然后进站。",en:"First buy the ticket, then enter the station.",py:"Xiān mǎi piào, ránhòu jìn zhàn."},{zh:"我们先吃饭，然后去看电影。",en:"We will eat first and then see a movie.",py:"Wǒmen xiān chī fàn, ránhòu qù kàn diànyǐng."}],exercises:[{q:"He was a student; later he became a teacher.",a:"他以前是学生，后来当了老师。",instr:"翻译",instrEn:"Translate into Chinese",body:"He was a student; later he became a teacher."},{q:"First wash your hands, then eat.",a:"先洗手，然后吃饭。",instr:"翻译",instrEn:"Translate into Chinese",body:"First wash your hands, then eat."},{q:"I went to the shop, then went home.",a:"我先去了商店，然后回家了。",instr:"翻译",instrEn:"Translate into Chinese",body:"I went to the shop, then went home."}],note:"后来侧重过去时间的推进；然后可以说明过去、现在或未来的一系列步骤。",source:"Discover China Student's Book Four (用户上传教材): Language in use",structureEn:"Past Situation + 后来 (hòulái, later) + Change; Action 1 + 然后 (ránhòu, then) + Action 2",noteEn:"后来 is about time moving on in the past; 然后 can link a series of steps in the past, present or future."},{id:"DC4-U08-2",name:"无论/不论/不管……都……",pinyin:"wúlùn / búlùn / bùguǎn ... dōu ...",type:"",explainEn:"Use it to mean 'no matter what/how/whether…, always…'.",structure:"无论/不论/不管 + 情况/疑问词，都 + 不变的结果",examples:[{zh:"无论天气怎么样，我都去。",en:"No matter what the weather is like, I will go.",py:"Wúlùn tiānqì zěnmeyàng, wǒ dōu qù."},{zh:"不管谁来，我们都欢迎。",en:"No matter who comes, we welcome them.",py:"Bùguǎn shéi lái, wǒmen dōu huānyíng."},{zh:"不论多忙，他都坚持运动。",en:"No matter how busy he is, he keeps exercising.",py:"Búlùn duō máng, tā dōu jiānchí yùndòng."}],exercises:[{q:"No matter where you go, I will help you.",a:"无论你去哪儿，我都会帮你。",instr:"翻译",instrEn:"Translate into Chinese",body:"No matter where you go, I will help you."},{q:"No matter how hard it is, I will try.",a:"不管多难，我都要试试。",instr:"翻译",instrEn:"Translate into Chinese",body:"No matter how hard it is, I will try."},{q:"No matter what he says, I won't change my mind.",a:"不论他说什么，我都不会改变主意。",instr:"翻译",instrEn:"Translate into Chinese",body:"No matter what he says, I won't change my mind."}],note:"三个词语体略有差别，“不论/无论”偏正式，结果句常用“都/也”。",source:"Discover China Student's Book Four (用户上传教材): Language in use",structureEn:"无论 (wúlùn) / 不论 (búlùn) / 不管 (bùguǎn, no matter) + Condition, 都 (dōu, still/always) + Result",noteEn:"The three words differ a little in style: 不论 and 无论 are more formal. The result part usually uses 都 or 也."},{id:"DC4-U08-3",name:"原来/果然/竟然（语气副词）",pinyin:"yuánlái / guǒrán / jìngrán",type:"",explainEn:"原来 means 'so that's it / it turns out'; 果然 means 'as expected'; 竟然 means 'unexpectedly'.",structure:"原来 + 新发现；果然 + 符合预期的事实；竟然 + 出乎意料的事实",examples:[{zh:"原来你也住在这里。",en:"So you live here too!",py:"Yuánlái nǐ yě zhù zài zhèlǐ."},{zh:"天气预报说会下雨，果然下雨了。",en:"The forecast said it would rain, and it did.",py:"Tiānqì yùbào shuō huì xià yǔ, guǒrán xià yǔ le."},{zh:"他竟然忘了自己的生日。",en:"Surprisingly, he forgot his own birthday.",py:"Tā jìngrán wàng le zìjǐ de shēngrì."}],exercises:[{q:"So this is your book!",a:"原来这是你的书！",instr:"翻译",instrEn:"Translate into Chinese",body:"So this is your book!"},{q:"As expected, he passed the exam.",a:"他果然通过了考试。",instr:"翻译",instrEn:"Translate into Chinese",body:"As expected, he passed the exam."},{q:"Surprisingly, she can speak Chinese.",a:"她竟然会说中文。",instr:"翻译",instrEn:"Translate into Chinese",body:"Surprisingly, she can speak Chinese."}],note:"三者不是同义词；情境分别为新发现、符合预期、出乎意料。",source:"Discover China Student's Book Four (用户上传教材): Language in use",structureEn:"原来 (yuánlái, it turns out) + Discovery; 果然 (guǒrán, as expected) + Result; 竟然 (jìngrán, surprisingly) + Unexpected Result",noteEn:"These three are not synonyms. Use them for a new discovery (原来), something that matches what you expected (果然), and something unexpected (竟然)."},{id:"DC4-U08-4",name:"算（是）（个人评价）",pinyin:"suàn (shì)",type:"",explainEn:"Use 算(是) to mean 'can be considered / count as' when giving an opinion.",structure:"人/事 + 算（是）+ 名词/形容词评价",examples:[{zh:"这算是个好办法。",en:"This counts as a good way to do it.",py:"Zhè suànshì ge hǎo bànfǎ."},{zh:"他的中文算不错了。",en:"His Chinese is quite good, all things considered.",py:"Tā de Zhōngwén suàn búcuò le."},{zh:"这里算是比较安静的地方。",en:"This can be considered a fairly quiet place.",py:"Zhèlǐ suànshì bǐjiào ānjìng de dìfang."}],exercises:[{q:"He can be considered a good teacher.",a:"他算是个好老师。",instr:"翻译",instrEn:"Translate into Chinese",body:"He can be considered a good teacher."},{q:"This is a pretty good result, all things considered.",a:"这个结果算不错了。",instr:"翻译",instrEn:"Translate into Chinese",body:"This is a pretty good result, all things considered."},{q:"We can count this as a success.",a:"这算是一次成功。",instr:"翻译",instrEn:"Translate into Chinese",body:"We can count this as a success."}],note:"“是”可以省略，表达主观评估或相对标准，不是绝对身份判定。",source:"Discover China Student's Book Four (用户上传教材): Language in use",structureEn:"Person / Thing + 算(是) (suàn shì, can be considered) + Noun / Judgment",noteEn:"是 can be left out. It gives a personal or relative judgment, not a statement of what something definitely is."}]},{num:9,title:"求之不得！",points:[{id:"DC4-U09-1",name:"看起来（似乎/看来）",pinyin:"kàn qǐlái",type:"",explainEn:"Use 看起来 to say what something seems like from what you see: 'looks / seems'.",structure:"主语 + 看起来 + 形容词/判断",examples:[{zh:"你看起来很累。",en:"You look tired.",py:"Nǐ kàn qǐlai hěn lèi."},{zh:"这家饭馆看起来不错。",en:"This restaurant looks good.",py:"Zhè jiā fànguǎn kàn qǐlai búcuò."},{zh:"他看起来比去年年轻。",en:"He looks younger than last year.",py:"Tā kàn qǐlai bǐ qùnián niánqīng."}],exercises:[{q:"She looks very happy.",a:"她看起来很高兴。",instr:"翻译",instrEn:"Translate into Chinese",body:"She looks very happy."},{q:"This place looks beautiful.",a:"这个地方看起来很美。",instr:"翻译",instrEn:"Translate into Chinese",body:"This place looks beautiful."},{q:"The problem seems difficult.",a:"这个问题看起来很难。",instr:"翻译",instrEn:"Translate into Chinese",body:"The problem seems difficult."}],note:"是根据外观获得的印象，不一定是客观事实；与“看见”不同。",source:"Discover China Student's Book Four (用户上传教材): Language in use",structureEn:"Subject + 看起来 (kàn qǐlái, looks/seems) + Adjective / Judgment",noteEn:'It is an impression based on how something looks, not necessarily a fact. It is different from 看见 ("to see").'},{id:"DC4-U09-2",name:"差点儿（几乎发生）",pinyin:"chàdiǎnr",type:"",explainEn:"Use 差点儿 to mean 'almost / nearly', for something that almost happened.",structure:"主语 + 差点儿 + 动词/动词短语 +（了）",examples:[{zh:"我差点儿迟到了。",en:"I was almost late.",py:"Wǒ chàdiǎnr chídào le."},{zh:"他差点儿摔倒。",en:"He almost fell.",py:"Tā chàdiǎnr shuāidǎo."},{zh:"我们差点儿忘了带票。",en:"We almost forgot the tickets.",py:"Wǒmen chàdiǎnr wàng le dài piào."}],exercises:[{q:"I almost missed the bus.",a:"我差点儿错过了公交车。",instr:"翻译",instrEn:"Translate into Chinese",body:"I almost missed the bus."},{q:"She almost cried.",a:"她差点儿哭了。",instr:"翻译",instrEn:"Translate into Chinese",body:"She almost cried."},{q:"I almost forgot your name.",a:"我差点儿忘了你的名字。",instr:"翻译",instrEn:"Translate into Chinese",body:"I almost forgot your name."}],note:"“差点儿”有时结合否定形式表达反预期结果，教学时应同时给出明确语境；英译练习以易辨认情况为主。",source:"Discover China Student's Book Four (用户上传教材): Language in use",structureEn:"Subject + 差点儿 (chàdiǎnr, almost) + Verb / Verb Phrase (+ 了 le)",noteEn:"差点儿 is sometimes used with a negative word (差点儿没……), and the meaning then depends on the situation, so it needs clear context. The translation practice sticks to the easier cases."},{id:"DC4-U09-3",name:"多……啊（感叹）",pinyin:"duō ... a",type:"",explainEn:"Use 多 + adjective + 啊 to show strong feeling: 'how…!'.",structure:"主语 + 多 + 形容词 + 啊！",examples:[{zh:"这里的风景多美啊！",en:"How beautiful the scenery is!",py:"Zhèlǐ de fēngjǐng duō měi a!"},{zh:"这个孩子多可爱啊！",en:"How lovely this child is!",py:"Zhège háizi duō kě'ài a!"},{zh:"今天的天气多好啊！",en:"How nice the weather is today!",py:"Jīntiān de tiānqì duō hǎo a!"}],exercises:[{q:"How delicious this food is!",a:"这道菜多好吃啊！",instr:"翻译",instrEn:"Translate into Chinese",body:"How delicious this food is!"},{q:"How happy she is!",a:"她多高兴啊！",instr:"翻译",instrEn:"Translate into Chinese",body:"How happy she is!"},{q:"How tall this building is!",a:"这座楼多高啊！",instr:"翻译",instrEn:"Translate into Chinese",body:"How tall this building is!"}],note:"这是感叹程度的“多”，不是询问数量的“多少”。",source:"Discover China Student's Book Four (用户上传教材): Language in use",structureEn:"Subject + 多 (duō, how) + Adjective + 啊 (a)!",noteEn:'This 多 shows strong feeling ("how…!"). It is not the 多 of 多少 that asks about quantity.'},{id:"DC4-U09-4",name:"是否（是不是，书面）",pinyin:"shìfǒu",type:"",explainEn:"Use 是否 to mean 'whether or not', often in formal Chinese.",structure:"主语 + 是否 + 动词/形容词/小句",examples:[{zh:"我不知道他是否会来。",en:"I do not know whether he will come.",py:"Wǒ bù zhīdào tā shìfǒu huì lái."},{zh:"请问你是否同意？",en:"May I ask whether you agree?",py:"Qǐngwèn nǐ shìfǒu tóngyì?"},{zh:"我们还没决定是否参加。",en:"We have not decided whether to join.",py:"Wǒmen hái méi juédìng shìfǒu cānjiā."}],exercises:[{q:"I don't know whether she is free.",a:"我不知道她是否有空。",instr:"翻译",instrEn:"Translate into Chinese",body:"I don't know whether she is free."},{q:"We are discussing whether to go.",a:"我们正在讨论是否去。",instr:"翻译",instrEn:"Translate into Chinese",body:"We are discussing whether to go."},{q:"Please confirm whether the time is suitable.",a:"请确认时间是否合适。",instr:"翻译",instrEn:"Translate into Chinese",body:"Please confirm whether the time is suitable."}],note:"常用于书面和正式提问，不能与“是不是”在所有语境中完全互换。",source:"Discover China Student's Book Four (用户上传教材): Language in use",structureEn:"Subject + 是否 (shìfǒu, whether or not) + Verb / Adjective / Clause",noteEn:"是否 is mostly used in writing and formal questions. It cannot replace 是不是 in every situation."}]},{num:10,title:"这个题目是不是太大了？",points:[{id:"DC4-U10-1",name:"动词来动词去（反复）",pinyin:"dòngcí lái dòngcí qù",type:"",explainEn:"Use Verb + 来 + Verb + 去 to show repeating an action again and again.",structure:"动词 + 来 + 同一动词 + 去 +（结果/评价）",examples:[{zh:"我想来想去，还是决定去。",en:"I thought it over and over and decided to go.",py:"Wǒ xiǎng lái xiǎng qù, háishi juédìng qù."},{zh:"他看来看去，没找到喜欢的。",en:"He looked again and again but found nothing he liked.",py:"Tā kàn lái kàn qù, méi zhǎodào xǐhuan de."},{zh:"我们讨论来讨论去，也没结果。",en:"We discussed it repeatedly but reached no result.",py:"Wǒmen tǎolùn lái tǎolùn qù, yě méi jiéguǒ."}],exercises:[{q:"She searched everywhere but didn't find it.",a:"她找来找去，还是没找到。",instr:"翻译",instrEn:"Translate into Chinese",body:"She searched everywhere but didn't find it."},{q:"I thought it over and over but still couldn't decide.",a:"我想来想去，还是不能决定。",instr:"翻译",instrEn:"Translate into Chinese",body:"I thought it over and over but still couldn't decide."},{q:"He walked back and forth.",a:"他走来走去。",instr:"翻译",instrEn:"Translate into Chinese",body:"He walked back and forth."}],note:"“来/去”在此不表示真实朝向，而是重复或往返动作。",source:"Discover China Student's Book Four (用户上传教材): Language in use",structureEn:"Verb + 来 (lái) + Same Verb + 去 (qù) + (Result), meaning 'back and forth'",noteEn:"Here 来 and 去 don't show a real direction; they show an action repeated again and again, or back and forth."},{id:"DC4-U10-2",name:"下去（动作继续）",pinyin:"xiàqù",type:"",explainEn:"Use 下去 after a verb to show that the action continues.",structure:"动词 + 下去；否定：动词 + 不 + 下去",examples:[{zh:"请继续说下去。",en:"Please keep talking.",py:"Qǐng jìxù shuō xiàqu."},{zh:"我们要坚持下去。",en:"We need to keep going.",py:"Wǒmen yào jiānchí xiàqu."},{zh:"这个故事太长了，我听不下去了。",en:"This story is too long; I cannot keep listening.",py:"Zhège gùshi tài cháng le, wǒ tīng bu xiàqu le."}],exercises:[{q:"I want to keep studying.",a:"我想继续学下去。",instr:"翻译",instrEn:"Translate into Chinese",body:"I want to keep studying."},{q:"Please go on reading.",a:"请读下去。",instr:"翻译",instrEn:"Translate into Chinese",body:"Please go on reading."},{q:"I can't keep working like this.",a:"我不能这样工作下去了。",instr:"翻译",instrEn:"Translate into Chinese",body:"I can't keep working like this."}],note:"引申为动作持续，不是空间向下的趋向。",source:"Discover China Student's Book Four (用户上传教材): Language in use",structureEn:"Verb + 下去 (xiàqù, keep going); Negative: Verb + 不 + 下去 (cannot continue)",noteEn:"Here 下去 means an action continues; it is not about moving downward."},{id:"DC4-U10-3",name:"把……花/用/浪费在……上",pinyin:"bǎ ... huā / yòng / làngfèi zài ... shàng",type:"",explainEn:"Use this pattern to say where you spend your time, money, or energy.",structure:"主语 + 把 + 时间/金钱/精力 + 花/用/浪费 + 在 + 事情 + 上",examples:[{zh:"我把很多时间花在学习中文上。",en:"I spend a lot of time studying Chinese.",py:"Wǒ bǎ hěn duō shíjiān huā zài xuéxí Zhōngwén shang."},{zh:"不要把钱浪费在没用的东西上。",en:"Do not waste money on useless things.",py:"Bú yào bǎ qián làngfèi zài méi yòng de dōngxi shang."},{zh:"她把精力都用在工作上了。",en:"She put all her energy into work.",py:"Tā bǎ jīnglì dōu yòng zài gōngzuò shang le."}],exercises:[{q:"He spends money on books.",a:"他把钱花在买书上。",instr:"翻译",instrEn:"Translate into Chinese",body:"He spends money on books."},{q:"I spend a lot of time on exercise.",a:"我把很多时间花在运动上。",instr:"翻译",instrEn:"Translate into Chinese",body:"I spend a lot of time on exercise."},{q:"Don't waste your time on games.",a:"别把时间浪费在游戏上。",instr:"翻译",instrEn:"Translate into Chinese",body:"Don't waste your time on games."}],note:"把的宾语是可支配资源；不要把“花在……上”误认为空间动作。",source:"Discover China Student's Book Four (用户上传教材): Language in use",structureEn:"Subject + 把 (bǎ) + Time/Money/Energy + 花 (huā, spend) / 用 (yòng, use) / 浪费 (làngfèi, waste) + 在 (zài) + Activity + 上 (shàng)",noteEn:"The object of 把 here is something you can use up, like time, money or energy. 花在……上 is not a physical movement."},{id:"DC4-U10-4",name:"即使……也……（让步）",pinyin:"jíshǐ ... yě ...",type:"",explainEn:"Use 即使…也… to mean 'even if…, still…'.",structure:"即使 + 不利/假设情况，也 + 结果/态度",examples:[{zh:"即使下雨，我也要去。",en:"Even if it rains, I will go.",py:"Jíshǐ xià yǔ, wǒ yě yào qù."},{zh:"即使很忙，他也会给妈妈打电话。",en:"Even when busy, he calls his mom.",py:"Jíshǐ hěn máng, tā yě huì gěi māma dǎ diànhuà."},{zh:"即使失败了，也不要放弃。",en:"Even if you fail, do not give up.",py:"Jíshǐ shībài le, yě bú yào fàngqì."}],exercises:[{q:"Even if it's cold, I will go out.",a:"即使天气很冷，我也会出去。",instr:"翻译",instrEn:"Translate into Chinese",body:"Even if it's cold, I will go out."},{q:"Even if I'm tired, I will finish it.",a:"即使我很累，也要做完。",instr:"翻译",instrEn:"Translate into Chinese",body:"Even if I'm tired, I will finish it."},{q:"Even if it's expensive, she wants to buy it.",a:"即使很贵，她也想买。",instr:"翻译",instrEn:"Translate into Chinese",body:"Even if it's expensive, she wants to buy it."}],note:"前句提出条件，后句行动或判断仍不改变。",source:"Discover China Student's Book Four (用户上传教材): Language in use",structureEn:"即使 (jíshǐ, even if) + Condition, 也 (yě, still) + Result",noteEn:"The first part gives a condition; the action or judgment in the second part still doesn't change."}]},{num:11,title:"回家的感觉真好！",points:[{id:"DC4-U11-1",name:"想……就……（随意选择）",pinyin:"xiǎng ... jiù ...",type:"",explainEn:"Use 想…就… to mean 'do whatever/whenever you want'.",structure:"主语 + 想 + 什么/去哪儿/做什么 + 就 + 相同疑问词/动作",examples:[{zh:"你想吃什么就吃什么。",en:"Eat whatever you like.",py:"Nǐ xiǎng chī shénme jiù chī shénme."},{zh:"我们想去哪儿就去哪儿。",en:"We can go wherever we want.",py:"Wǒmen xiǎng qù nǎr jiù qù nǎr."},{zh:"她想什么时候休息就什么时候休息。",en:"She rests whenever she wants.",py:"Tā xiǎng shénme shíhou xiūxi jiù shénme shíhou xiūxi."}],exercises:[{q:"Do whatever you want.",a:"你想做什么就做什么。",instr:"翻译",instrEn:"Translate into Chinese",body:"Do whatever you want."},{q:"Drink whatever you like.",a:"你想喝什么就喝什么。",instr:"翻译",instrEn:"Translate into Chinese",body:"Drink whatever you like."},{q:"Go whenever you want.",a:"你想什么时候去就什么时候去。",instr:"翻译",instrEn:"Translate into Chinese",body:"Go whenever you want."}],note:"教材强调前后疑问词对应，表示自由选择；两个主语可以相同也可以不同。",source:"Discover China Student's Book Four (用户上传教材): Language in use",structureEn:"Subject + 想 (xiǎng, want) + Choice, 就 (jiù, then) + Same Choice/Action",noteEn:"The textbook stresses that the question words in both parts match, which shows free choice. The two subjects can be the same or different."},{id:"DC4-U11-2",name:"动词1着 + 动词2（动作方式）",pinyin:"dòngcí yī zhe + dòngcí èr",type:"",explainEn:"Use Verb 1 + 着 + Verb 2 when the first action is the way or state of doing the second.",structure:"主语 + 动词1 + 着 +（宾语1）+ 动词2 +（宾语2）",examples:[{zh:"她笑着说话。",en:"She speaks while smiling.",py:"Tā xiào zhe shuōhuà."},{zh:"他站着吃饭。",en:"He eats while standing.",py:"Tā zhàn zhe chī fàn."},{zh:"孩子背着书包上学。",en:"The child goes to school carrying a schoolbag.",py:"Háizi bēi zhe shūbāo shàngxué."}],exercises:[{q:"He listens to music while lying down.",a:"他躺着听音乐。",instr:"翻译",instrEn:"Translate into Chinese",body:"He listens to music while lying down."},{q:"She came in smiling.",a:"她笑着走了进来。",instr:"翻译",instrEn:"Translate into Chinese",body:"She came in smiling."},{q:"He came in holding a book.",a:"他拿着一本书进来了。",instr:"翻译",instrEn:"Translate into Chinese",body:"He came in holding a book."}],note:"动词1着往往说明动词2发生时的姿势或方式；不是单纯表示两个独立动作。",source:"Discover China Student's Book Four (用户上传教材): Language in use",structureEn:"Subject + Verb 1 + 着 (zhe, while/in this manner) + (Object 1) + Verb 2 + (Object 2)",noteEn:"Verb 1 + 着 usually describes the posture or manner in which Verb 2 happens; it is not just two separate actions."},{id:"DC4-U11-3",name:"之所以……是因为……（原因强调）",pinyin:"zhī suǒyǐ ... shì yīnwèi ...",type:"",explainEn:"Use 之所以…是因为… to explain and emphasize the reason.",structure:"主语 + 之所以 + 结果，是因为 + 原因",examples:[{zh:"我之所以迟到，是因为堵车。",en:"The reason I was late is that there was traffic.",py:"Wǒ zhīsuǒyǐ chídào, shì yīnwèi dǔchē."},{zh:"他之所以学习中文，是因为喜欢中国文化。",en:"He studies Chinese because he likes Chinese culture.",py:"Tā zhīsuǒyǐ xuéxí Zhōngwén, shì yīnwèi xǐhuan Zhōngguó wénhuà."},{zh:"我们之所以没去，是因为下雨了。",en:"We didn't go because it rained.",py:"Wǒmen zhīsuǒyǐ méi qù, shì yīnwèi xià yǔ le."}],exercises:[{q:"The reason she is tired is that she worked all day.",a:"她之所以累，是因为工作了一整天。",instr:"翻译",instrEn:"Translate into Chinese",body:"The reason she is tired is that she worked all day."},{q:"The reason I called is that I need help.",a:"我之所以打电话，是因为需要帮助。",instr:"翻译",instrEn:"Translate into Chinese",body:"The reason I called is that I need help."},{q:"The reason we are happy is that we passed the exam.",a:"我们之所以高兴，是因为通过了考试。",instr:"翻译",instrEn:"Translate into Chinese",body:"The reason we are happy is that we passed the exam."}],note:"“之所以”引出结果，“是因为”后说明原因；不要颠倒其逻辑关系。",source:"Discover China Student's Book Four (用户上传教材): Language in use",structureEn:"Subject + 之所以 (zhī suǒyǐ, the reason why) + Result, 是因为 (shì yīnwèi, is because) + Reason",noteEn:"之所以 introduces the result, and 是因为 is followed by the reason. Don't reverse them."},{id:"DC4-U11-4",name:"以A为B（将A当作B）",pinyin:"yǐ A wéi B",type:"",explainEn:"Use 以 A 为 B to mean 'take/use A as B'. It is formal.",structure:"主语 + 以 + A + 为 + B",examples:[{zh:"我们以北京为起点。",en:"We take Beijing as the starting point.",py:"Wǒmen yǐ Běijīng wéi qǐdiǎn."},{zh:"这次活动以环保为主题。",en:"This event takes environmental protection as its theme.",py:"Zhè cì huódòng yǐ huánbǎo wéi zhǔtí."},{zh:"学校以学生为中心。",en:"The school puts students at the center.",py:"Xuéxiào yǐ xuésheng wéi zhōngxīn."}],exercises:[{q:"We use English as the main language.",a:"我们以英语为主要语言。",instr:"翻译",instrEn:"Translate into Chinese",body:"We use English as the main language."},{q:"This class takes travel as its topic.",a:"这节课以旅游为主题。",instr:"翻译",instrEn:"Translate into Chinese",body:"This class takes travel as its topic."},{q:"We put safety first.",a:"我们以安全为第一。",instr:"翻译",instrEn:"Translate into Chinese",body:"We put safety first."}],note:"教材区分“以……为……”（当作）与“以……为标准”（参照）；要看B的具体含义。",source:"Discover China Student's Book Four (用户上传教材): Language in use",structureEn:"Subject + 以 (yǐ, take) + A + 为 (wéi, as) + B",noteEn:'The textbook separates 以……为…… ("take A as B") from 以……为标准 ("use A as the standard"). Look at what B actually means.'}]},{num:12,title:"有付出，才有收获。",points:[{id:"DC4-U12-1",name:"才……呢（加强语气）",pinyin:"cái ... ne",type:"",explainEn:"Use 才…呢 to argue back or correct someone: 'X is the one that…' or 'no way…!'.",structure:"主语 + 才 + 动词/形容词 + 呢",examples:[{zh:"你才说得对呢！",en:"You're the one who's really right!",py:"Nǐ cái shuō de duì ne!"},{zh:"这才好呢！",en:"Now this is really good!",py:"Zhè cái hǎo ne!"},{zh:"他才不怕呢！",en:"He certainly isn't afraid!",py:"Tā cái bú pà ne!"}],exercises:[{q:"I really don't want to go!",a:"我才不想去呢！",instr:"翻译",instrEn:"Translate into Chinese",body:"I really don't want to go!"},{q:"This one isn't expensive — that one is the expensive one!",a:"这个不贵，那个才贵呢！",instr:"翻译",instrEn:"Translate into Chinese",body:"This one isn't expensive — that one is the expensive one!"},{q:"He doesn't know — she's the one who knows the answer!",a:"他不知道，她才知道答案呢！",instr:"翻译",instrEn:"Translate into Chinese",body:"He doesn't know — she's the one who knows the answer!"}],note:"常用于反驳、更正或强调对方预期之外的事实，语气应根据语境选择。",source:"Discover China Student's Book Four (用户上传教材): Language in use",structureEn:"Subject + 才 (cái, 'is the one that…' / 'no way') + Verb/Adjective + 呢 (ne)",noteEn:"It is often used to argue back, correct someone, or stress a fact the other person didn't expect. Choose the tone to fit the situation."},{id:"DC4-U12-2",name:"何必……呢（不必如此）",pinyin:"hébì ... ne",type:"",explainEn:"Use 何必…呢 to say 'why bother…?' when something is unnecessary.",structure:"何必 + 动词/动词短语 + 呢？",examples:[{zh:"这么小的事，何必生气呢？",en:"Why get angry over such a small matter?",py:"Zhème xiǎo de shì, hébì shēngqì ne?"},{zh:"我们已经知道了，何必再问呢？",en:"We already know; why ask again?",py:"Wǒmen yǐjīng zhīdào le, hébì zài wèn ne?"},{zh:"天气这么好，何必待在家里呢？",en:"The weather is so nice; why stay at home?",py:"Tiānqì zhème hǎo, hébì dāi zài jiā li ne?"}],exercises:[{q:"Why worry so much?",a:"何必这么担心呢？",instr:"翻译",instrEn:"Translate into Chinese",body:"Why worry so much?"},{q:"Why spend so much money?",a:"何必花这么多钱呢？",instr:"翻译",instrEn:"Translate into Chinese",body:"Why spend so much money?"},{q:"Why argue about this?",a:"何必为这件事争论呢？",instr:"翻译",instrEn:"Translate into Chinese",body:"Why argue about this?"}],note:"反问句表达不赞成或认为没有必要，不是真正询问原因。",source:"Discover China Student's Book Four (用户上传教材): Language in use",structureEn:"何必 (hébì, why bother) + Verb / Verb Phrase + 呢 (ne)?",noteEn:"This is a rhetorical question: it shows you disagree or think something is unnecessary. It is not really asking for a reason."},{id:"DC4-U12-3",name:"别说A，就是B也/都……（让步列举）",pinyin:"biéshuō A, jiùshì B yě / dōu ...",type:"",explainEn:"Use 别说 A，就是 B 都… to mean 'let alone A; even B…'.",structure:"别说 + 较难/极端情况，就是 + 较简单情况 + 也/都 + 谓语",examples:[{zh:"别说跑十公里了，就是跑一公里我也累。",en:"Never mind ten kilometers — even one kilometer makes me tired.",py:"Biéshuō pǎo shí gōnglǐ le, jiùshì pǎo yì gōnglǐ wǒ yě lèi."},{zh:"别说买房了，就是房租也很贵。",en:"Never mind buying a home — even rent is expensive.",py:"Biéshuō mǎi fáng le, jiùshì fángzū yě hěn guì."},{zh:"别说孩子了，就是大人也不明白。",en:"Never mind children — even adults don't understand.",py:"Biéshuō háizi le, jiùshì dàren yě bù míngbai."}],exercises:[{q:"Never mind speaking Chinese — I can't even read it.",a:"别说说中文了，就是看中文我也不会。",instr:"翻译",instrEn:"Translate into Chinese",body:"Never mind speaking Chinese — I can't even read it."},{q:"Never mind a new car — even an old car is expensive.",a:"别说新车了，就是旧车也很贵。",instr:"翻译",instrEn:"Translate into Chinese",body:"Never mind a new car — even an old car is expensive."},{q:"Never mind an hour — I don't even have ten minutes.",a:"别说一个小时了，就是十分钟我也没有。",instr:"翻译",instrEn:"Translate into Chinese",body:"Never mind an hour — I don't even have ten minutes."}],note:"强调连较低条件都达不到；A与B需要构成强弱对比。",source:"Discover China Student's Book Four (用户上传教材): Language in use",structureEn:"别说 (biéshuō, let alone) + Harder Case A, 就是 (jiùshì, even) + Easier Case B + 也/都 (yě/dōu) + Result",noteEn:`It stresses that even the easier case B doesn't work out, so A is out of the question. A and B need to be a clear "harder vs. easier" pair.`},{id:"DC4-U12-4",name:"一直/不断（持续或反复）",pinyin:"yìzhí / búduàn",type:"",explainEn:"一直 means 'all along / continuously'; 不断 means 'repeatedly / keep on'.",structure:"主语 + 一直 + 动词/状态；主语 + 不断 + 动词/变化",examples:[{zh:"我一直在学习中文。",en:"I have been studying Chinese all along.",py:"Wǒ yìzhí zài xuéxí Zhōngwén."},{zh:"他不断问问题。",en:"He keeps asking questions.",py:"Tā búduàn wèn wèntí."},{zh:"公司不断改进服务。",en:"The company keeps improving its service.",py:"Gōngsī búduàn gǎijìn fúwù."}],exercises:[{q:"She has always supported me.",a:"她一直支持我。",instr:"翻译",instrEn:"Translate into Chinese",body:"She has always supported me."},{q:"We keep learning new things.",a:"我们不断学习新东西。",instr:"翻译",instrEn:"Translate into Chinese",body:"We keep learning new things."},{q:"He has been waiting here.",a:"他一直在这儿等。",instr:"翻译",instrEn:"Translate into Chinese",body:"He has been waiting here."}],note:"“一直”强调时间连续，“不断”常强调动作多次或发展持续。",source:"Discover China Student's Book Four (用户上传教材): Language in use",structureEn:"Subject + 一直 (yìzhí, continuously) + Verb/State; Subject + 不断 (búduàn, again and again) + Verb/Change",noteEn:"一直 stresses that something goes on without a break; 不断 often stresses an action happening again and again, or steady change."}]}],s={series:e,unit:4,lessons:n};export{s as default,n as lessons,e as series,t as unit};
